// Generates crate/src/data.rs from prices.json so the crate needs no JSON parser.

function f(v) {
  if (v === null || v === undefined) return 'None';
  const s = Number.isInteger(v) ? `${v}.0` : String(v);
  return `Some(${s})`;
}

function str(s) {
  return JSON.stringify(s ?? '');
}

function cw(o) {
  if (!o) return '&[]';
  const parts = Object.entries(o)
    .filter(([, v]) => v !== null && v !== undefined)
    .map(([k, v]) => `(${str(k)}, ${Number.isInteger(v) ? `${v}.0` : v})`);
  return `&[${parts.join(', ')}]`;
}

export function toRust(doc) {
  const out = [
    '// @generated by scripts/update.mjs from prices.json. Do not edit by hand.',
    'use crate::{LongContext, Price};',
    '',
    `/// Date the table was generated (ISO 8601).`,
    `pub const GENERATED: &str = ${str(doc.generated)};`,
    '',
    'pub static PRICES: &[Price] = &[',
  ];
  for (const m of doc.models) {
    const lc = m.long_context
      ? `Some(LongContext { threshold_tokens: ${m.long_context.threshold_tokens}, input: ${f(m.long_context.input)}, output: ${f(m.long_context.output)}, cache_read: ${f(m.long_context.cache_read)}, cache_write: ${cw(m.long_context.cache_write)}, batch_input: ${f(m.long_context.batch_input)}, batch_output: ${f(m.long_context.batch_output)} })`
      : 'None';
    out.push(
      `    Price { provider: ${str(m.provider)}, model: ${str(m.model)}, aliases: &[${m.aliases.map(str).join(', ')}], status: ${str(m.status)}, input: ${f(m.input)}, output: ${f(m.output)}, cache_read: ${f(m.cache_read)}, cache_write: ${cw(m.cache_write)}, batch_input: ${f(m.batch_input)}, batch_output: ${f(m.batch_output)}, long_context: ${lc}, source_url: ${str(m.source_url)}, checked: ${str(m.checked)} },`,
    );
  }
  out.push('];', '');
  return out.join('\n');
}
